    Editor --> Plugins","theme":"auto"}}},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"1.1 Core Extensions"}]},{"type":"paragraph","content":[{"type":"text","text":"The editor canvas integrates several native Tiptap extensions to provide foundational rich text capabilities:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standard Formatting","marks":[{"type":"bold"}]},{"type":"text","text":": Bold, Italic, Strikethrough, Underline, Highlight, Subscript, Superscript, Code, Text Align, Blockquote."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Text Styles","marks":[{"type":"bold"}]},{"type":"text","text":": The "},{"type":"text","text":"TextStyle","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Color","marks":[{"type":"code"}]},{"type":"text","text":" extensions enable arbitrary text color hex properties to be stored directly in the document AST."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hyperlinks","marks":[{"type":"bold"}]},{"type":"text","text":": The "},{"type":"text","text":"Link","marks":[{"type":"code"}]},{"type":"text","text":" extension maintains URL mapping across the AST, with a custom-built floating action menu and Insert Link dialog handling the user experience."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"1.2 Document AST Structure"}]},{"type":"paragraph","content":[{"type":"text","text":"ProseMirror represents documents as a nested node tree (JSON) rather than flat HTML, which guarantees structured data validation and seamless operational transformation (OT) mapping:"}]},{"type":"codeBlock","attrs":{"language":"json"},"content":[{"type":"text","text":"{
