Tiptap Editor A                                                Tiptap Editor B"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"State updates","marks":[{"type":"bold"}]},{"type":"text","text":": Any change in Client A’s Tiptap editor is captured as an incremental update transaction in the local "},{"type":"text","text":"Y.Doc","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Offline Persistence (","marks":[{"type":"bold"}]},{"type":"text","text":"y-indexeddb","marks":[{"type":"code"}]},{"type":"text","text":")","marks":[{"type":"bold"}]},{"type":"text","text":": Before transmission, the transaction is saved locally to the browser's IndexedDB. This guarantees no data is lost if the internet drops."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Websocket relay","marks":[{"type":"bold"}]},{"type":"text","text":": The transaction updates are serialized into binary blobs, base64 encoded, and transmitted to the Go backend WebSocket server using the "},{"type":"text","text":"sync","marks":[{"type":"code"}]},{"type":"text","text":" message type."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Broadcast","marks":[{"type":"bold"}]},{"type":"text","text":": The Go backend stores the cumulative base64 updates in-memory (and in "},{"type":"text","text":"document_versions","marks":[{"type":"code"}]},{"type":"text","text":" during debounced snapshots) and broadcasts the updates to all other connected clients in the same document room."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Integration","marks":[{"type":"bold"}]},{"type":"text","text":": Client B receives the updates, applies them to their local "},{"type":"text","text":"Y.Doc","marks":[{"type":"code"}]},{"type":"text","text":", and the collaboration extension updates the Tiptap editor state seamlessly."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2.2 WebSocket Communication Payloads"}]},{"type":"paragraph","content":[{"type":"text","text":"WebSockets handle Yjs syncing and presence messages. The Go backend router accepts connections at "},{"type":"text","text":"/api/ws","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Client-to-Server Messages"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Join room","marks":[{"type":"bold"}]},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"json"},"content":[{"type":"text","text":"{
