}"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"State Mapping","marks":[{"type":"bold"}]},{"type":"text","text":": Upon receiving peer cursor notifications, the custom extension feeds meta information into the ProseMirror transaction:"}]},{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"tr.setMeta("presence-cursor", { userId, username, color, position, anchor });"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Decoration Rendering","marks":[{"type":"bold"}]},{"type":"text","text":": The plugin maps positions to active coordinates, drawing:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inline highlight ranges","marks":[{"type":"bold"}]},{"type":"text","text":" (from "},{"type":"text","text":"anchor","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"position","marks":[{"type":"code"}]},{"type":"text","text":") styled with transluscent colors ("},{"type":"text","text":"${color}33","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Caret line widgets","marks":[{"type":"bold"}]},{"type":"text","text":" styled with the peer user's color."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hover Labels","marks":[{"type":"bold"}]},{"type":"text","text":" displaying the editor username temporarily."}]}]}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Shadow DOM UI Macro Plugin Architecture"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Kollab allows runtime loading of dynamic macros and custom widgets via a "},{"type":"text","text":"Shadow DOM Web Components","marks":[{"type":"bold"}]},{"type":"text","text":" model. This provides complete isolation, ensuring CSS stylesheets from plugins cannot pollute the core application design."}]},{"type":"macroBlock","attrs":{"type":"mermaid","config":{"code":"---
