}, [editor, isEditing]);"}]},{"type":"paragraph","content":[{"type":"text","text":"ProseMirror dynamically updates the host DOM element attributes, setting "},{"type":"text","text":"contenteditable="true"","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"contenteditable="false"","marks":[{"type":"code"}]},{"type":"text","text":" accordingly."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"5.1 Editor Layout: Sticky Header"}]},{"type":"paragraph","content":[{"type":"text","text":"The Editor is housed in the "},{"type":"text","text":"EditorCanvas","marks":[{"type":"code"}]},{"type":"text","text":" component, which manages a highly optimized scroll layout. The "},{"type":"text","text":"EditorHeader","marks":[{"type":"code"}]},{"type":"text","text":" (title, author, metadata) and the "},{"type":"text","text":"EditorToolbar","marks":[{"type":"code"}]},{"type":"text","text":" (formatting tools) are wrapped in a sticky container ("},{"type":"text","text":"position: "sticky", top: 0, zIndex: 10","marks":[{"type":"code"}]},{"type":"text","text":"), keeping the essential document controls and context visible at all times as the user scrolls down long documents."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. CSS Contenteditable Selectors"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In order to avoid messy class additions, we leverage ProseMirror's native state indicator attribute ("},{"type":"text","text":"contenteditable","marks":[{"type":"code"}]},{"type":"text","text":") in our stylesheet "},{"type":"text","text":"index.css"},{"type":"text","text":":"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Editing Layout Guides","marks":[{"type":"bold"}]},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"css"},"content":[{"type":"text","text":".ProseMirror[contenteditable="true"] .layout-column {
  border: 1px dashed rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.01);
}"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seamless Read-Only Presentation","marks":[{"type":"bold"}]},{"type":"text","text":":"}]},{"type":"codeBlock","attrs":{"language":"css"},"content":[{"type":"text","text":".ProseMirror[contenteditable="false"] .layout-column {
  border: 1px solid transparent;
  padding: 0;
  background: transparent;
}"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Node View Guards"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Custom React Node Views (such as "},{"type":"text","text":"CalloutPanelView.tsx"},{"type":"text","text":" or "},{"type":"text","text":"ImageComponent.tsx"},{"type":"text","text":") receive the parent "},{"type":"text","text":"editor","marks":[{"type":"code"}]},{"type":"text","text":" as a prop in "},{"type":"text","text":"NodeViewProps","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"To lock down views:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Action Bars","marks":[{"type":"bold"}]},{"type":"text","text":": Action headers, floating grids, or delete buttons are wrapped in "},{"type":"text","text":"{editor?.isEditable && ( ... )}","marks":[{"type":"code"}]},{"type":"text","text":" to prevent them from mounting at all."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interaction Handlers","marks":[{"type":"bold"}]},{"type":"text","text":": Click and double-click actions check "},{"type":"text","text":"if (!editor?.isEditable) return;","marks":[{"type":"code"}]},{"type":"text","text":" at entry."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cursor Accents","marks":[{"type":"bold"}]},{"type":"text","text":": CSS selectors within the node wrapper alter "},{"type":"text","text":"cursor: isEditable ? "pointer" : "default"","marks":[{"type":"code"}]},{"type":"text","text":" and remove hover border animations."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Page Analytics Algorithm"}]},{"type":"paragraph","content":[{"type":"text","text":"The read-only "},{"type":"text","text":"EditorHeader","marks":[{"type":"code"}]},{"type":"text","text":" receives the canvas analytics state setter through the "},{"type":"text","text":"setAnalyticsDialogOpen","marks":[{"type":"code"}]},{"type":"text","text":" prop. Selecting "},{"type":"text","text":"Analytics","marks":[{"type":"bold"}]},{"type":"text","text":" sets "},{"type":"text","text":"analyticsOpen","marks":[{"type":"code"}]},{"type":"text","text":", mounts "},{"type":"text","text":"EditorAnalyticsDialog","marks":[{"type":"code"}]},{"type":"text","text":", and fetches live document analytics for the active document. Keeping this prop name aligned with "},{"type":"text","text":"EditorHeaderProps","marks":[{"type":"code"}]},{"type":"text","text":" is required: a mismatched prop leaves the header control without a callable state transition."}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"To compute structural statistics recursively, the page analytics reader parses the editor's JSON node output rather than parsing raw text."}]},{"type":"paragraph","content":[{"type":"text","text":"The parser traverses the content tree:"}]},{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"const visit = (node: any) => {
  if (node.type === "paragraph") paragraphs++;
  else if (node.type === "heading") headings++;
  else if (node.type === "table") tables++;
  else if (node.type === "customImage" || node.type === "image") images++;
  else if (node.type === "calloutPanel") callouts++;
  else if (node.type === "inlineStatus") statuses++;
  else if (node.type === "inlineDate") dates++;
  else if (node.type === "taskItem") tasks++;

  if (node.content) {
    node.content.forEach(visit);
  }
};

editor.getJSON().content?.forEach(visit);"}]},{"type":"paragraph","content":[{"type":"text","text":"This ensures block-level elements nested deep inside custom columns or tables are counted accurately.
Word counts are calculated by cleaning and splitting the plaintext output of "},{"type":"text","text":"editor.getText()","marks":[{"type":"code"}]},{"type":"text","text":".
Est. Reading Time assumes a standard adult reading pace of 200 words per minute."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Presentation Mode (Deck Viewer)"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A toggle to instantly convert a standard scrolling Kollab document into a full-screen, paginated slide deck, ideal for town halls or project pitches."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"9.1 Mode Trigger and Layout"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Toggle","marks":[{"type":"bold"}]},{"type":"text","text":": Users can click a "Present" button in the document header."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rendering","marks":[{"type":"bold"}]},{"type":"text","text":": The React host wrapper transitions from a vertical scroll container to a horizontal, full-viewport slider component."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"9.2 Slide Pagination Logic"}]},{"type":"paragraph","content":[{"type":"text","text":"The engine paginates the document's AST dynamically based on two delimiter rules:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading 1 Break","marks":[{"type":"bold"}]},{"type":"text","text":": Every "},{"type":"text","text":"heading","marks":[{"type":"code"}]},{"type":"text","text":" node with "},{"type":"text","text":"level: 1","marks":[{"type":"code"}]},{"type":"text","text":" automatically signals the start of a new slide."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manual Slide Break Macro","marks":[{"type":"bold"}]},{"type":"text","text":": Authors can insert a "},{"type":"text","text":"<slideBreak>","marks":[{"type":"code"}]},{"type":"text","text":" macro anywhere in the document to force a break."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The viewer then renders only the chunk of AST nodes that fall between the active slide's delimiters, providing a clean, focused presentation without altering the underlying document state."}]},{"type":"paragraph","content":[{"type":"text","text":"Source: design/02_editor_core.md"}]}]}

