{"type":"doc","content":[{"type":"macroBlock","attrs":{"type":"page-properties","config":{"properties":[{"key":"Area","value":"Engineering","type":"text"},{"key":"Audience","value":"Developers and operators","type":"text"},{"key":"Availability","value":"Demonstration","type":"text"}]}}},{"type":"paragraph","content":[{"type":"text","text":"Kollab persists a Tiptap document as a JSON object with "},{"type":"text","text":"type: "doc"","marks":[{"type":"code"}]},{"type":"text","text":" and a "},{"type":"text","text":"content","marks":[{"type":"code"}]},{"type":"text","text":" array. Each child must match a registered ProseMirror node. Arbitrary macro names do not become working features merely because they appear in JSON."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Native blocks and atom macros"}]},{"type":"paragraph","content":[{"type":"text","text":"A native container owns editable child nodes. For example, "},{"type":"text","text":"calloutPanel","marks":[{"type":"code"}]},{"type":"text","text":" accepts "},{"type":"text","text":"block+","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"tabsContainer","marks":[{"type":"code"}]},{"type":"text","text":" accepts "},{"type":"text","text":"tabItem+","marks":[{"type":"code"}]},{"type":"text","text":"; a "},{"type":"text","text":"tabItem","marks":[{"type":"code"}]},{"type":"text","text":" accepts "},{"type":"text","text":"block+","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"macroBlock","marks":[{"type":"code"}]},{"type":"text","text":" is an atom: its "},{"type":"text","text":"attrs.type","marks":[{"type":"code"}]},{"type":"text","text":" selects a renderer and "},{"type":"text","text":"attrs.config","marks":[{"type":"code"}]},{"type":"text","text":" supplies renderer-specific settings."}]},{"type":"codeBlock","attrs":{"language":"json"},"content":[{"type":"text","text":"{
