}"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Collaborative Syncing Loop (Yjs & WebSockets)"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Real-time multi-user editing is achieved by anchoring Tiptap's collaboration extension to a shared "},{"type":"text","text":"Yjs document (","marks":[{"type":"bold"}]},{"type":"text","text":"Y.Doc","marks":[{"type":"code"}]},{"type":"text","text":")","marks":[{"type":"bold"}]},{"type":"text","text":" synced over a WebSocket network loop."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2.1 Sync Architecture"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Client A (Y.Doc) <──[WS binary updates]──> Go WebSocket Hub ──> Client B (Y.Doc)
