":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Page Analytics Algorithm"}]},{"type":"paragraph","content":[{"type":"text","text":"The read-only "},{"type":"text","text":"EditorHeader","marks":[{"type":"code"}]},{"type":"text","text":" receives the canvas analytics state setter through the "},{"type":"text","text":"setAnalyticsDialogOpen","marks":[{"type":"code"}]},{"type":"text","text":" prop. Selecting "},{"type":"text","text":"Analytics","marks":[{"type":"bold"}]},{"type":"text","text":" sets "},{"type":"text","text":"analyticsOpen","marks":[{"type":"code"}]},{"type":"text","text":", mounts "},{"type":"text","text":"EditorAnalyticsDialog","marks":[{"type":"code"}]},{"type":"text","text":", and fetches live document analytics for the active document. Keeping this prop name aligned with "},{"type":"text","text":"EditorHeaderProps","marks":[{"type":"code"}]},{"type":"text","text":" is required: a mismatched prop leaves the header control without a callable state transition."}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" 🟢 Completed"}]}]},{"type":"paragraph","content":[{"type":"text","text":"To compute structural statistics recursively, the page analytics reader parses the editor's JSON node output rather than parsing raw text."}]},{"type":"paragraph","content":[{"type":"text","text":"The parser traverses the content tree:"}]},{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"const visit = (node: any) => {
  if (node.type === "paragraph") paragraphs++;
  else if (node.type === "heading") headings++;
  else if (node.type === "table") tables++;
  else if (node.type === "customImage" || node.type === "image") images++;
  else if (node.type === "calloutPanel") callouts++;
  else if (node.type === "inlineStatus") statuses++;
  else if (node.type === "inlineDate") dates++;
  else if (node.type === "taskItem") tasks++;

  if (node.content) {
    node.content.forEach(visit);
  }
};

editor.getJSON().content?.forEach(visit);"}]},{"type":"paragraph","content":[{"type":"text","text":"This ensures block-level elements nested deep inside custom columns or tables are counted accurately.
