    tag_id VARCHAR(255) REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (document_id, tag_id)
);"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.2 Frontend Integration"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Global Page","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"/my/tags","marks":[{"type":"code"}]},{"type":"text","text":" renders "},{"type":"text","text":"TagsView","marks":[{"type":"code"}]},{"type":"text","text":" to manage tag definitions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document Tags","marks":[{"type":"bold"}]},{"type":"text","text":": Rendered in "},{"type":"text","text":"DocumentTags.tsx","marks":[{"type":"code"}]},{"type":"text","text":" at the bottom of the page via a filterable MUI "},{"type":"text","text":"Popover","marks":[{"type":"code"}]},{"type":"text","text":", allowing on-the-fly tag creation."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. User Initials Avatar"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"UserAvatar","marks":[{"type":"code"}]},{"type":"text","text":" component ensures a consistent, premium display of user profiles. It uses an algorithm to extract initials:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Split the trimmed display name by whitespace."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extract the first character of each word."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Join, uppercase, and slice to a maximum of 3 characters."}]}]}]},{"type":"codeBlock","attrs":{"language":"typescript"},"content":[{"type":"text","text":"export const getInitials = (name: string): string => {
  if (!name) return "?";
  return name.trim().split(/\s+/).filter(Boolean).map(w => w.charAt(0)).join("").toUpperCase().slice(0, 3);
};"}]},{"type":"paragraph","content":[{"type":"text","text":"Source: design/08_metadata_and_social.md"}]}]}

{"type":"doc","content":[{"type":"macroBlock","attrs":{"type":"page-properties","config":{"properties":[{"key":"Area","value":"Engineering","type":"text"},{"key":"Audience","value":"Developers and operators","type":"text"},{"key":"Availability","value":"Reference; see section status","type":"text"}]}}},{"type":"calloutPanel","attrs":{"type":"note","title":"Design reference"},"content":[{"type":"paragraph","content":[{"type":"text","text":"This page follows the repository design document. Some sections retain proposed or historical behavior. Check the curated Architecture walkthrough and current source code before treating a planned capability as available."}]}]},{"type":"paragraph","content":[{"type":"text","text":"This document specifies the routing architecture for Kollab documents, transitioning from strict UUID-based URLs to memorable, human-readable "nicknames" or slugs."}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Routing & Resolution Logic"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Kollab URLs must support a dual-resolution system where users can safely share either the underlying immutable UUID or the dynamic, human-readable slug."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"1.1 Dual Routing Strategy"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"UUID Routing","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"https://kollab.internal/docs/{uuid}","marks":[{"type":"code"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The fallback mechanism. If a link is constructed using the "},{"type":"text","text":"id","marks":[{"type":"code"}]},{"type":"text","text":", the backend will instantly resolve it. This guarantees that deep-links and bookmarks never break even if the document is renamed."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Slug Routing","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"https://kollab.internal/docs/{slug}","marks":[{"type":"code"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The preferred, default URL shown in the browser address bar. The frontend router will attempt to fetch by "},{"type":"text","text":"slug","marks":[{"type":"code"}]},{"type":"text","text":". If the API returns a 404, it assumes the parameter might be an invalid slug and throws a "Page Not Found"."}]}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"1.2 Database Schema Updates"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"documents","marks":[{"type":"code"}]},{"type":"text","text":" table requires a new, globally unique column for the URL nickname."}]},{"type":"codeBlock","attrs":{"language":"sql"},"content":[{"type":"text","text":"ALTER TABLE documents ADD COLUMN slug VARCHAR(255) UNIQUE;

-- Create an index to optimize the frontend slug-based GET requests
CREATE INDEX idx_documents_slug ON documents(slug);"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Slug Generation & Conflict Resolution"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2.1 Auto-Generation (The Default Path)"}]},{"type":"paragraph","content":[{"type":"text","text":"When a user types the title of a new document (e.g., "Q3 Engineering Roadmap"), the frontend debounces the input and automatically generates a proposed slug by:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Converting all text to lowercase."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replacing spaces and special characters with hyphens."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stripping non-alphanumeric characters.
"},{"type":"text","text":"(Result: ","marks":[{"type":"italic"}]},{"type":"text","text":"q3-engineering-roadmap","marks":[{"type":"code"}]},{"type":"text","text":")","marks":[{"type":"italic"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"2.2 Uniqueness Constraints (Collision Handling)"}]},{"type":"paragraph","content":[{"type":"text","text":"Since slugs are globally unique across the workspace, the backend API enforces strict duplicate prevention on "},{"type":"text","text":"POST /documents","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PUT /documents","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"q3-engineering-roadmap","marks":[{"type":"code"}]},{"type":"text","text":" already exists:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The backend appends a sequential integer suffix (e.g., "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-2","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The system iteratively checks "},{"type":"text","text":"q3-engineering-roadmap-1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"q3-engineering-roadmap-2","marks":[{"type":"code"}]},{"type":"text","text":" until a unique slot is found."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The successful slug is persisted."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Custom Nickname Overrides"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Users are not strictly bound to the auto-generated title-based slug."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.1 The Page Details Modal"}]},{"type":"paragraph","content":[{"type":"text","text":"Users can open a "Page Info / Settings" dialog from the document header. This dialog includes a text input allowing them to explicitly override the Page Nickname."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.2 Validation Rules for Custom Slugs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":": Must match the regex "},{"type":"text","text":"^[a-z0-9-]+$","marks":[{"type":"code"}]},{"type":"text","text":" (only lowercase letters, numbers, and hyphens)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Uniqueness Check","marks":[{"type":"bold"}]},{"type":"text","text":": When the user clicks "Save," the frontend fires a pre-flight "},{"type":"text","text":"GET /api/documents/check-slug?slug={input}","marks":[{"type":"code"}]},{"type":"text","text":" to instantly validate availability before submitting the form."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redirection","marks":[{"type":"bold"}]},{"type":"text","text":": If a user successfully changes the slug of an existing page, any user currently viewing the page via the old slug will remain connected via their WebSocket session, and the frontend will silently use the History API to push the new URL to their address bar without reloading."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Slug Aliases & Permanent Redirection"}]},{"type":"calloutPanel","attrs":{"type":"note","title":"NOTE"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Status:","marks":[{"type":"bold"}]},{"type":"text","text":" ⚪ Planned"}]}]},{"type":"paragraph","content":[{"type":"text","text":"To prevent broken links when a document is renamed or its slug is explicitly changed, Kollab implements a historical alias system."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"4.1 Alias Table"}]},{"type":"codeBlock","attrs":{"language":"sql"},"content":[{"type":"text","text":"CREATE TABLE IF NOT EXISTS document_slug_aliases (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    document_id VARCHAR(255) NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    old_slug VARCHAR(255) UNIQUE NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
);"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"4.2 Redirect Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"When a user visits a slug (e.g. "},{"type":"text","text":"GET /docs/q3-roadmap","marks":[{"type":"code"}]},{"type":"text","text":"):"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The backend searches the "},{"type":"text","text":"documents","marks":[{"type":"code"}]},{"type":"text","text":" table for "},{"type":"text","text":"slug = 'q3-roadmap'","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If no active document is found, it queries "},{"type":"text","text":"document_slug_aliases","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"old_slug = 'q3-roadmap'","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an alias is found, it fetches the document's current active slug (e.g. "},{"type":"text","text":"q4-roadmap","marks":[{"type":"code"}]},{"type":"text","text":") and issues a "},{"type":"text","text":"301 Moved Permanently","marks":[{"type":"code"}]},{"type":"text","text":" to the new route."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If neither exist, a standard "},{"type":"text","text":"404 Not Found","marks":[{"type":"code"}]},{"type":"text","text":" is returned."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Source: design/12_page_routing_and_slugs.md"}]}]}
